import{af as r,ad as o,z as i,J as s,ab as a,x as n}from"./chunks/framework.DAW84IGp.js";const b=JSON.parse('{"title":"RH2 LED indicators","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices/rtk/handheld/leds.md","filePath":"devices/rtk/handheld/leds.md"}'),d={name:"devices/rtk/handheld/leds.md"};function l(c,e,h,p,u,f){const t=o("LedDemo");return i(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794431872000"},[e[0]||(e[0]=a('<h1 id="rh2-led-indicators" tabindex="-1">RH2 LED indicators <a class="header-anchor" href="#rh2-led-indicators" aria-label="Permalink to &quot;RH2 LED indicators&quot;">​</a></h1><p>RH2 has the <a href="/docs/pr/47/devices/capabilities/rgb-status-leds">RGB status LED capability</a>. In the standard firmware, it uses the display described here. Application-controlled lights can provide separate feedback, so first check whether you are looking at charging/status or at a running application&#39;s indication. See the <a href="/docs/pr/47/devices/rtk/handheld/external#front">RH2 exterior guide</a> for the enclosure layout.</p><h2 id="charging-status" tabindex="-1">Charging status <a class="header-anchor" href="#charging-status" aria-label="Permalink to &quot;Charging status&quot;">​</a></h2><p>The standard RGB charging display changes colour with the approximate battery level:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Charging status colour</th></tr></thead><tbody><tr><td>Below 30%</td><td>Red</td></tr><tr><td>30% to below 70%</td><td>Orange</td></tr><tr><td>70% to below 90%</td><td>Yellow-green</td></tr><tr><td>90% or more</td><td>Green</td></tr></tbody></table><p>Brightness varies in steps about every half-second while charging below approximately 99%. At about 99% or above, that variation stops. Green starts at about 90%; it is not an exact full-battery indication or proof of an RTK fix.</p>',6)),n(t,{mode:"rh2"}),e[1]||(e[1]=a('<p>Do not apply the four-bar, 95% charging rule from Pro3 or the older ProN/Zero/Enviro guides to RH2.</p><h2 id="off-charge-status" tabindex="-1">Off-charge status <a class="header-anchor" href="#off-charge-status" aria-label="Permalink to &quot;Off-charge status&quot;">​</a></h2><p>When armed and active, the standard status display can reflect positioning state and low battery. A configured resting colour takes precedence over that default indication, and an inactive device normally turns the status display off. Applications and alarms can also control the lights.</p><p>For this reason, a green or red light by itself is not a reliable statement of RTK accuracy, upload success or a hardware fault. Check the application&#39;s positioning/accuracy information and the latest successful communication.</p><h2 id="application-controlled-feedback" tabindex="-1">Application-controlled feedback <a class="header-anchor" href="#application-controlled-feedback" aria-label="Permalink to &quot;Application-controlled feedback&quot;">​</a></h2><p>The <a href="/docs/pr/47/devices/api/sdks/toit/applications/survey/#cloud-submission">Survey application</a> flashes green for a successfully submitted survey point and red for a submission error. Those are application events, not the charging colour table above. Other applications can choose different patterns.</p><p>For another device or an unfamiliar pattern, start with the <a href="/docs/pr/47/guides/leds">LED guide</a>.</p>',7))])}const m=r(d,[["render",l]]);export{b as __pageData,m as default};
